    private static final Map<String,ShutdownTicket> shutdownTickets=new java.util.concurrent.ConcurrentHashMap<>();
    private static volatile long shutdownAt;
    private static final class ShutdownTicket {final String address;final long expires=System.currentTimeMillis()+60000;ShutdownTicket(String address){this.address=address;}}

    private static synchronized void power(HttpExchange x){
        if(!"POST".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}if(!guard(x))return;
        try{
            String action=new String(x.getRequestBody().readNBytes(128),StandardCharsets.UTF_8).trim();String address=x.getRemoteAddress().getAddress().getHostAddress();
            if(updates!=null&&updates.required()&&!"cancel".equals(action)){sendText(x,426,"Atualização obrigatória. Abra o agente Windows para instalar.");return;}
            shutdownTickets.entrySet().removeIf(e->e.getValue().expires<System.currentTimeMillis());
            if("prepare".equals(action)){
                if(shutdownAt>System.currentTimeMillis()){sendText(x,409,"O desligamento já está agendado.");return;}
                shutdownTickets.entrySet().removeIf(e->e.getValue().address.equals(address));
                if(shutdownTickets.size()>32){sendText(x,429,"Muitos pedidos pendentes.");return;}
                String ticket=UUID.randomUUID().toString();shutdownTickets.put(ticket,new ShutdownTicket(address));
                sendText(x,200,"{\"ticket\":"+q(ticket)+",\"expiresIn\":60}","application/json; charset=utf-8");return;
            }
            if("cancel".equals(action)){
                if(shutdownAt<=System.currentTimeMillis()){sendText(x,409,"Não há desligamento deste agente para cancelar.");return;}
                runShutdown("/a");shutdownAt=0;sendText(x,200,"{\"cancelled\":true}","application/json; charset=utf-8");return;
            }
            if(action.startsWith("confirm:")){
                ShutdownTicket ticket=shutdownTickets.remove(action.substring(8));
                if(ticket==null||ticket.expires<System.currentTimeMillis()||!ticket.address.equals(address)){sendText(x,409,"Confirmação expirada. Solicite o desligamento novamente.");return;}
                if(shutdownAt>System.currentTimeMillis()){sendText(x,409,"Desligamento já solicitado.");return;}
                runShutdown("/s","/f","/t","30","/c","MarlicoBot: desligamento confirmado. Programas serão fechados e alterações não salvas serão perdidas.");
                shutdownAt=System.currentTimeMillis()+30000;shutdownTickets.clear();
                if(trayIcon!=null)trayIcon.displayMessage("MarlicoBot · desligamento","Desligamento em 30 segundos. Cancele na aba Privacidade e conexão.",TrayIcon.MessageType.WARNING);
                sendText(x,200,"{\"scheduled\":true,\"seconds\":30}","application/json; charset=utf-8");return;
            }
            sendText(x,400,"Ação de energia inválida.");
        }catch(Exception e){sendText(x,503,"O Windows não aceitou o comando de energia. Verifique as permissões do usuário e pedidos de desligamento já existentes.");}
    }
    private static void runShutdown(String...args)throws Exception{
        List<String> command=new ArrayList<>();command.add(Paths.get(System.getenv("SystemRoot"),"System32","shutdown.exe").toString());command.addAll(Arrays.asList(args));
        Process process=new ProcessBuilder(command).redirectErrorStream(true).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();
        if(!process.waitFor(5,TimeUnit.SECONDS)){process.destroy();throw new IOException("Comando expirou.");}if(process.exitValue()!=0)throw new IOException("Windows recusou o comando.");
    }

    public static void main(String[] args) throws Exception {
        if(args.length>0&&"--self-test".equals(args[0])){PORT=0;byte[] secret=new byte[32];new SecureRandom().nextBytes(secret);token=Base64.getUrlEncoder().withoutPadding().encodeToString(secret);startServer();try{selfTest();}finally{server.stop(0);}return;}
        if(args.length>0&&"--inventory-check".equals(args[0])){Inventory i=inventory();if(i.fields.size()<8)throw new IllegalStateException("Inventário incompleto: "+i.fields.size()+" categorias.");System.out.println("Inventário local OK: "+i.fields.size()+" categorias de hardware/SO e "+i.apps.size()+" programas instalados.");return;}
        Files.createDirectories(HOME); token=loadToken();
        SwingUtilities.invokeAndWait(Agent::buildUi);
        updates=new AppUpdates(HOME,new AppUpdates.Listener(){
            public void changed(String status,boolean available,boolean required,boolean busy){SwingUtilities.invokeLater(()->{updateLabel.setText("<html>"+html((required?"Atualização obrigatória · ":"")+status)+"</html>");updateButton.setText(available?"Baixar atualização":"Verificar atualizações");updateButton.setEnabled(!busy);if(required){liveStreaming.set(false);liveSessionAllowed.set(false);}});}
            public void discovered(String version,boolean required){SwingUtilities.invokeLater(()->{if(trayIcon!=null)trayIcon.displayMessage("MarlicoBot "+version,required?"Atualização obrigatória. Abra o painel para instalar.":"Nova versão disponível. Abra o painel para atualizar.",TrayIcon.MessageType.INFO);});}
            public void installerReady(){SwingUtilities.invokeLater(()->{showFromTray();if(brandedConfirm("Atualização pronta","O download oficial foi verificado. Instalar agora? O Windows solicitará permissão de administrador e o agente será reiniciado. Suas configurações serão mantidas.","Instalar agora","Depois"))updates.install();});}
        });updates.start();
        try { startServer(); running=true; setStatus("Agente ativo · MarlicoBot 1.3.3",new Color(255,57,200)); }
        catch(Exception e) { setStatus("Não foi possível abrir a porta "+PORT+": "+e.getMessage(),new Color(255,150,130)); }
        ScheduledExecutorService refresh=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"metrics");t.setDaemon(true);return t;});
        refresh.scheduleAtFixedRate(()->{try{Snapshot s=snapshot();latestSnapshot=s;SwingUtilities.invokeLater(()->render(s));}catch(Exception ignored){}if(liveStreaming.get()&&System.currentTimeMillis()-lastLiveCapture>30000){liveStreaming.set(false);liveSessionAllowed.set(false);}SwingUtilities.invokeLater(Agent::updateLiveStatus);},0,3,TimeUnit.SECONDS);
        Runtime.getRuntime().addShutdownHook(new Thread(()->{running=false;if(server!=null)server.stop(0);refresh.shutdownNow();}));
    }
