    private static void startServer() throws IOException {
        server=HttpServer.create(new InetSocketAddress("0.0.0.0",PORT),24);
        server.createContext("/api/status",x->{if(!"GET".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}if(!guard(x))return;Snapshot s=latestSnapshot;if(s==null)s=snapshot();sendText(x,200,statusJson(s),"application/json; charset=utf-8");});
        server.createContext("/api/processes",x->{if(!"GET".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}if(!guard(x))return;sendText(x,200,processesJson(),"application/json; charset=utf-8");});
        server.createContext("/api/inventory",x->{if(!"GET".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}if(!guard(x))return;try{Inventory i=latestInventory;if(i==null){i=inventory();latestInventory=i;}sendText(x,200,inventoryJson(i),"application/json; charset=utf-8");}catch(Exception e){sendText(x,503,"Inventário temporariamente indisponível.");}});
        server.createContext("/api/pair",Agent::pair);
        server.createContext("/api/screen",Agent::screen);
        server.createContext("/api/screen/live",Agent::liveScreen);
        server.createContext("/api/power",Agent::power);
        server.setExecutor(Executors.newFixedThreadPool(4,r->{Thread t=new Thread(r,"api-readonly");t.setDaemon(true);return t;}));server.start();
    }
    private static void selfTest() throws Exception {
        int port=server.getAddress().getPort();int checks=0;
        if(request(port,"/api/status",null,"GET").code!=401)throw new AssertionError("status endpoint must require authentication");checks++;
        HttpResult status=request(port,"/api/status",token,"GET");if(status.code!=200||!status.body.contains("\"readOnly\":true")||!status.body.contains("\"cpuPercent\":"))throw new AssertionError("status endpoint JSON invalid");checks++;
        HttpResult processes=request(port,"/api/processes",token,"GET");if(processes.code!=200||!processes.body.contains("\"processes\":["))throw new AssertionError("process endpoint JSON invalid");checks++;
        if(request(port,"/api/inventory",null,"GET").code!=401)throw new AssertionError("inventory endpoint must require authentication");checks++;
        Inventory old=latestInventory;latestInventory=new Inventory(new String[][]{{"Windows","Test"}},new ArrayList<>());HttpResult inv=request(port,"/api/inventory",token,"GET");latestInventory=old;if(inv.code!=200||!inv.body.contains("\"installedPrograms\":[]")||!inv.body.contains("\"Windows\""))throw new AssertionError("inventory endpoint JSON invalid");checks++;
        if(request(port,"/api/screen",null,"GET").code!=401)throw new AssertionError("screen endpoint must authenticate before prompting");checks++;
        if(request(port,"/api/screen",token,"POST").code!=405)throw new AssertionError("screen endpoint must reject non-GET requests");checks++;
        if(request(port,"/api/control",token,"GET").code!=404)throw new AssertionError("remote control endpoint must not exist");checks++;
        System.out.println("OK: "+checks+" verificações locais do agente Windows (autorização, telemetria, processos, captura protegida e ausência de controle remoto).");
    }
    private static HttpResult request(int port,String path,String credential,String method)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(3000);c.setReadTimeout(10000);if(credential!=null)c.setRequestProperty("Authorization","Bearer "+credential);int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();String body="";if(in!=null)try(InputStream stream=in){body=new String(stream.readAllBytes(),StandardCharsets.UTF_8);}c.disconnect();return new HttpResult(code,body);}
    private static final class HttpResult{final int code;final String body;HttpResult(int c,String b){code=c;body=b;}}
    private static boolean authorized(HttpExchange x){try{String got=x.getRequestHeaders().getFirst("Authorization");if(got==null||!got.startsWith("Bearer "))return false;return MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),got.substring(7).getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
    private static boolean localRequest(HttpExchange x){try{InetAddress a=x.getRemoteAddress().getAddress();return a.isSiteLocalAddress()||a.isLoopbackAddress();}catch(Exception e){return false;}}
    private static boolean guard(HttpExchange x){if(!localRequest(x)){sendText(x,403,"Acesso permitido apenas pela rede local.");return false;}if(!authorized(x)){sendText(x,401,"Autorização inválida.");return false;}if(updates!=null&&updates.required()&&!"/api/power".equals(x.getRequestURI().getPath())){sendText(x,426,"Atualização obrigatória. Abra o agente Windows para instalar.");return false;}return true;}
    private static void pair(HttpExchange x){
        if(!"POST".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}
        if(!localRequest(x)){sendText(x,403,"Pareamento permitido apenas pela rede local.");return;}
        try(InputStream body=x.getRequestBody()){String request=new String(body.readNBytes(128),StandardCharsets.UTF_8);if(!"MarlicoBot Android pairing request".equals(request)){sendText(x,400,"Pedido de pareamento inválido.");return;}}catch(Exception e){sendText(x,400,"Pedido de pareamento inválido.");return;}
        if(!pairPending.compareAndSet(false,true)){sendText(x,409,"Já existe um pedido de pareamento em andamento.");return;}
        String requester=x.getRemoteAddress().getAddress().getHostAddress();final boolean[] accepted={false};final CountDownLatch answer=new CountDownLatch(1);
        SwingUtilities.invokeLater(()->{try{if(frame!=null){frame.setVisible(true);frame.setExtendedState(Frame.NORMAL);frame.setAlwaysOnTop(true);frame.toFront();frame.requestFocus();}accepted[0]=brandedConfirm("Pedido de pareamento","Um aplicativo MarlicoBot na rede local ("+requester+") quer vincular-se a este computador para consultar métricas, solicitar visualização de tela e desligamento forçado após confirmação no aparelho. Autorize somente dispositivos seus.","Autorizar pareamento","Recusar");}finally{if(frame!=null)frame.setAlwaysOnTop(false);answer.countDown();}});
        try{if(!answer.await(90,TimeUnit.SECONDS)){sendText(x,504,"O pedido de pareamento expirou.");return;}if(!accepted[0]){sendText(x,403,"Pareamento recusado no computador.");return;}sendText(x,200,"{\"token\":"+q(token)+",\"port\":"+PORT+"}","application/json; charset=utf-8");}
        catch(InterruptedException e){Thread.currentThread().interrupt();sendText(x,503,"Pareamento interrompido.");}
        finally{pairPending.set(false);}
    }
    private static void sendText(HttpExchange x,int code,String text){sendText(x,code,text,"text/plain; charset=utf-8");}
    private static void sendText(HttpExchange x,int code,String text,String type){try{byte[] b=text.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",type);x.getResponseHeaders().set("Cache-Control","no-store");x.sendResponseHeaders(code,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}catch(Exception ignored){try{x.close();}catch(Exception ignored2){}}}
    private static boolean screenConsent(String title,String message) throws InterruptedException {
        CountDownLatch answer=new CountDownLatch(1);java.util.concurrent.atomic.AtomicInteger choice=new java.util.concurrent.atomic.AtomicInteger();
        SwingUtilities.invokeLater(()->{boolean visible=frame!=null&&frame.isVisible();int state=frame==null?0:frame.getExtendedState();try{if(frame!=null){frame.setVisible(true);frame.setExtendedState(Frame.NORMAL);frame.toFront();}choice.set(screenConsentChoice(title,message));if(choice.get()==2&&!setUnattendedScreenAllowed(true)){choice.set(0);brandedMessage("Permissão não salva","O acesso sem supervisão não pôde ser salvo. Autorize novamente ou confira a pasta de configurações do agente.");}if(unattendedConsentCheck!=null)unattendedConsentCheck.setSelected(unattendedScreenAllowed);}finally{if(frame!=null){frame.setAlwaysOnTop(false);frame.setExtendedState(state);if(!visible)frame.setVisible(false);}answer.countDown();}});
        return answer.await(95,TimeUnit.SECONDS)&&choice.get()!=0;
    }
    private static int screenConsentChoice(String title,String message){
        final int[] choice={0};JDialog dialog=new JDialog(frame,title,Dialog.ModalityType.APPLICATION_MODAL);dialog.setUndecorated(true);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        JPanel shell=new JPanel(new BorderLayout(0,16));shell.setBackground(BG);shell.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),new EmptyBorder(19,22,18,22)));dialog.setContentPane(shell);
        JLabel heading=label(title,TEXT,17);heading.setFont(new Font("Segoe UI",Font.BOLD,17));shell.add(heading,BorderLayout.NORTH);
        JTextArea copy=new JTextArea(message+"\n\nEscolha permitir uma vez ou habilitar o acesso sem supervisão para próximas solicitações.");copy.setEditable(false);copy.setFocusable(false);copy.setLineWrap(true);copy.setWrapStyleWord(true);copy.setFont(new Font("Segoe UI",Font.PLAIN,13));copy.setForeground(TEXT);copy.setBackground(BG);copy.setPreferredSize(new Dimension(570,115));shell.add(copy,BorderLayout.CENTER);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);JButton deny=secondaryButton("Recusar"),once=secondaryButton("Permitir uma vez"),always=button("Permitir acesso à tela sem supervisão");
        deny.addActionListener(e->dialog.dispose());once.addActionListener(e->{choice[0]=1;dialog.dispose();});always.addActionListener(e->{choice[0]=2;dialog.dispose();});actions.add(deny);actions.add(once);actions.add(always);shell.add(actions,BorderLayout.SOUTH);
        dialog.getRootPane().setDefaultButton(deny);dialog.getRootPane().registerKeyboardAction(e->dialog.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);dialog.pack();dialog.setLocationRelativeTo(frame);dialog.setAlwaysOnTop(true);
        javax.swing.Timer expiry=new javax.swing.Timer(90000,e->dialog.dispose());expiry.setRepeats(false);expiry.start();dialog.setVisible(true);expiry.stop();return choice[0];
    }
    private static BufferedImage captureMonitor(int monitor)throws Exception {
        GraphicsDevice[] devices=GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices();
        if(monitor<0||monitor>=devices.length)throw new IOException("Monitor desconectado. Atualize a lista de telas.");
        GraphicsDevice device=devices[monitor];return new Robot(device).createScreenCapture(device.getDefaultConfiguration().getBounds());
    }
    private static void captureError(HttpExchange x,Exception e){
        try{Files.writeString(HOME.resolve("capture-errors.log"),Instant.now()+" "+e.getClass().getSimpleName()+": "+e.getMessage()+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception ignored){}
        sendText(x,500,"Falha na captura ("+e.getClass().getSimpleName()+"). Mantenha a sessão do Windows aberta e desbloqueada. Consulte capture-errors.log no agente.");
    }
    private static void sendImage(HttpExchange x,byte[] bytes,String consent)throws IOException{
        x.getResponseHeaders().set("Content-Type","image/jpeg");x.getResponseHeaders().set("Cache-Control","no-store");x.getResponseHeaders().set("X-Capture-Consent",consent);x.sendResponseHeaders(200,bytes.length);try(OutputStream out=x.getResponseBody()){out.write(bytes);}
    }
    private static void screen(HttpExchange x){
        if(!"GET".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}if(!guard(x))return;
        if(System.currentTimeMillis()-lastCapture.get()<5000||!capturePending.compareAndSet(false,true)){sendText(x,429,"Já existe uma captura em andamento. Aguarde alguns segundos.");return;}
        try{int monitor=monitorParam(x);boolean unattended=unattendedScreenAllowed;if(!unattended&&!screenConsent("Pedido de captura de tela","O MarlicoBot quer enviar UMA imagem deste monitor ao aparelho ou chat que fez o pedido. Autorize somente se reconhece a solicitação. Este pedido expira em 90 segundos.")){sendText(x,403,"Captura recusada ou autorização expirada.");return;}
            Thread.sleep(250);byte[] bytes=jpeg(captureMonitor(monitor));if(unattended&&!unattendedScreenAllowed){sendText(x,403,"Acesso sem supervisão revogado no Windows.");return;}lastCapture.set(System.currentTimeMillis());if(trayIcon!=null)trayIcon.displayMessage("MarlicoBot · captura de tela","Uma captura única foi solicitada por aparelho pareado.",TrayIcon.MessageType.INFO);sendImage(x,bytes,"one-shot");
        }catch(Exception e){captureError(x,e);}finally{capturePending.set(false);}
    }
    private static void liveScreen(HttpExchange x){
        if(!guard(x))return;
        try{
            int monitor=monitorParam(x);
            if("POST".equals(x.getRequestMethod())){
                String command=new String(x.getRequestBody().readNBytes(32),StandardCharsets.UTF_8).trim();
                if("start".equals(command)){
                    if(!liveConsentPending.compareAndSet(false,true)){sendText(x,409,"Há uma solicitação aguardando autorização.");return;}
                    try{
                        if(liveStreaming.get()){sendText(x,409,"Já existe uma transmissão. Pare a sessão anterior no Windows.");return;}
                        boolean unattended=unattendedScreenAllowed;if(!unattended&&!screenConsent("Pedido de acesso remoto","Um aparelho pareado em "+x.getRemoteAddress().getAddress().getHostAddress()+" quer visualizar os monitores ao vivo, sem controlar mouse ou teclado. Você pode encerrar a sessão no agente. Pedido válido por 90 segundos.")){sendText(x,403,"Visualização recusada ou autorização expirada.");return;}
                        if(unattended&&!unattendedScreenAllowed){sendText(x,403,"Acesso sem supervisão revogado no Windows.");return;}
                        liveSession=UUID.randomUUID().toString();liveSessionAllowed.set(true);lastLiveCapture=System.currentTimeMillis();liveStreaming.set(true);updateLiveStatus();
                        sendText(x,200,"{\"session\":"+q(liveSession)+"}","application/json; charset=utf-8");
                    }finally{liveConsentPending.set(false);}return;
                }
                if("stop".equals(command)){if(validLiveSession(x)){liveStreaming.set(false);liveSessionAllowed.set(false);updateLiveStatus();}sendText(x,200,"{\"active\":false}","application/json; charset=utf-8");return;}
                sendText(x,400,"Comando inválido.");return;
            }
            if(!"GET".equals(x.getRequestMethod())){sendText(x,405,"Método não permitido.");return;}
            if(!validLiveSession(x)||!liveSessionAllowed.get()||!liveStreaming.get()){sendText(x,403,"Sessão encerrada no Windows. Inicie um novo acesso remoto.");return;}
            if(!liveCapturePending.compareAndSet(false,true)){sendText(x,429,"Aguarde o próximo quadro.");return;}
            try{byte[] bytes=jpeg(captureMonitor(monitor));if(!liveStreaming.get()||!validLiveSession(x)){sendText(x,403,"Compartilhamento interrompido.");return;}lastLiveCapture=System.currentTimeMillis();sendImage(x,bytes,"continuous");}finally{liveCapturePending.set(false);}
        }catch(Exception e){captureError(x,e);}
    }
    private static boolean validLiveSession(HttpExchange x){return liveSession!=null&&liveSession.equals(x.getRequestHeaders().getFirst("X-View-Session"));}
    private static int monitorParam(HttpExchange x){String raw=x.getRequestURI().getRawQuery();int monitor=0;if(raw!=null)for(String part:raw.split("&")){String[] kv=part.split("=",2);if(kv.length==2&&"monitor".equals(kv[0]))monitor=Integer.parseInt(kv[1]);}if(monitor<0||monitor>=GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices().length)throw new IllegalArgumentException("Monitor inexistente.");return monitor;}
    private static synchronized boolean setUnattendedScreenAllowed(boolean allowed){
        if(!allowed){unattendedScreenAllowed=false;liveStreaming.set(false);liveSessionAllowed.set(false);updateLiveStatus();}
        try{Properties p=new Properties();if(Files.exists(PREFS))try(InputStream in=Files.newInputStream(PREFS)){p.load(in);}p.setProperty("unattendedScreenAllowed",Boolean.toString(allowed));try(OutputStream out=Files.newOutputStream(PREFS)){p.store(out,"MarlicoBot PC agent settings");}unattendedScreenAllowed=allowed;return true;}
        catch(Exception e){if(allowed)unattendedScreenAllowed=false;return false;}
    }
    private static void updateLiveStatus(){SwingUtilities.invokeLater(()->{boolean active=liveStreaming.get()&&System.currentTimeMillis()-lastLiveCapture<30000;if(stopShareButton!=null){stopShareButton.setEnabled(active);for(Component c:stopShareButton.getParent().getComponents())if(c instanceof JLabel&&"live-status".equals(c.getName())){((JLabel)c).setText(active?"Visualização ao vivo ativa · quadro atualizado agora":"Transmissão de tela parada");((JLabel)c).setForeground(active?new Color(255,150,130):MUTED);}}if(statusLabel!=null)statusLabel.setText(active?"TELA COMPARTILHADA AO VIVO":"Agente ativo · MarlicoBot 1.3.3");if(trayIcon!=null)trayIcon.setToolTip(active?"MarlicoBot PC · visualização ao vivo em andamento":"MarlicoBot PC · monitor ativo");});}
    private static byte[] jpeg(BufferedImage source)throws IOException{int w=source.getWidth(),h=source.getHeight();double scale=Math.min(1.0,Math.min(1280.0/w,720.0/h));int nw=Math.max(1,(int)(w*scale)),nh=Math.max(1,(int)(h*scale));BufferedImage target=new BufferedImage(nw,nh,BufferedImage.TYPE_INT_RGB);Graphics2D g=target.createGraphics();g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BILINEAR);g.drawImage(source,0,0,nw,nh,Color.BLACK,null);g.dispose();ByteArrayOutputStream bytes=new ByteArrayOutputStream();javax.imageio.ImageWriter writer=ImageIO.getImageWritersByFormatName("jpg").next();javax.imageio.ImageWriteParam params=writer.getDefaultWriteParam();params.setCompressionMode(javax.imageio.ImageWriteParam.MODE_EXPLICIT);params.setCompressionQuality(.64f);try(javax.imageio.stream.ImageOutputStream stream=ImageIO.createImageOutputStream(bytes)){writer.setOutput(stream);writer.write(null,new javax.imageio.IIOImage(target,null,null),params);}finally{writer.dispose();}return bytes.toByteArray();}
    private static Inventory inventory(){String ps="""
        $ErrorActionPreference='SilentlyContinue'; $ProgressPreference='SilentlyContinue'; [Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false); $OutputEncoding=[Console]::OutputEncoding
        function clean($v){ if($null -eq $v){return ''}; return ([string]$v).Replace("`r",' ').Replace("`n",' ').Replace("`t",' ').Replace('|','/') }
        function field($k,$v){ [Console]::Out.WriteLine(('FIELD'+"`t"+$k+"`t"+(clean $v))) }
        $os=Get-CimInstance Win32_OperatingSystem; $cs=Get-CimInstance Win32_ComputerSystem; $cpu=Get-CimInstance Win32_Processor | Select-Object -First 1; $board=Get-CimInstance Win32_BaseBoard | Select-Object -First 1; $bios=Get-CimInstance Win32_BIOS | Select-Object -First 1
        $gpus=@(Get-CimInstance Win32_VideoController | ForEach-Object { $_.Name + $(if($_.DriverVersion){' · driver '+$_.DriverVersion}) }); $dims=@(Get-CimInstance Win32_PhysicalMemory); $ram=($dims | ForEach-Object { $gb=[math]::Round($_.Capacity/1GB,0); $desc=($_.Manufacturer+' '+$gb+' GB'+$(if($_.Speed){' · '+$_.Speed+' MHz'})); $desc.Trim() }) -join ' / '
        $drives=@(Get-CimInstance Win32_DiskDrive | ForEach-Object { $_.Model+' · '+[math]::Round($_.Size/1GB,0)+' GB'+$(if($_.MediaType){' · '+$_.MediaType}) }) -join ' / '
        $volumes=@(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | ForEach-Object { $_.DeviceID+' '+[math]::Round($_.FreeSpace/1GB,1)+' GB livres de '+[math]::Round($_.Size/1GB,1)+' GB' }) -join ' / '
        $net=@(Get-NetAdapter -Physical | ForEach-Object { $_.Name+' · '+$_.Status+' · '+$_.LinkSpeed+' · '+$_.MacAddress }) -join ' / '
        field 'Sistema operacional' ($os.Caption+' · versão '+$os.Version+' · build '+$os.BuildNumber+' · '+$os.OSArchitecture)
        field 'Fabricante e modelo' ($cs.Manufacturer+' · '+$cs.Model)
        field 'Processador' ($cpu.Name+' · '+$cpu.NumberOfCores+' núcleos · '+$cpu.NumberOfLogicalProcessors+' threads')
        field 'Memória instalada' ([math]::Round($cs.TotalPhysicalMemory/1GB,1).ToString()+' GB · '+$dims.Count+' módulo(s) · '+$ram)
        field 'Placa de vídeo' ($gpus -join ' / ')
        field 'Placa-mãe' ($board.Manufacturer+' · '+$board.Product)
        field 'BIOS' ($bios.Manufacturer+' · '+$bios.SMBIOSBIOSVersion+' · '+$bios.ReleaseDate)
        field 'Unidades físicas' $drives
        field 'Volumes' $volumes
        field 'Adaptadores de rede' $net
        $roots=@('HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*','HKLM:\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*','HKCU:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*','HKCU:\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*')
        $apps=@(foreach($root in $roots){ Get-ItemProperty $root | Where-Object { $_.DisplayName -and -not $_.SystemComponent } | ForEach-Object { [pscustomobject]@{Name=(clean $_.DisplayName);Version=(clean $_.DisplayVersion);Publisher=(clean $_.Publisher)} } }); $apps=@($apps | Group-Object { $_.Name+'|'+$_.Version } | ForEach-Object { $_.Group[0] } | Sort-Object Name,Version)
        foreach($a in $apps){[Console]::Out.WriteLine(('APP'+"`t"+$a.Name+"`t"+$a.Version+"`t"+$a.Publisher))}
        """;
        String encoded=Base64.getEncoder().encodeToString(ps.getBytes(StandardCharsets.UTF_16LE));String raw=run(30000,"powershell.exe","-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-EncodedCommand",encoded);Map<String,String> fields=new LinkedHashMap<>();List<String[]> apps=new ArrayList<>();for(String line:raw.split("\\R")){String[] p=line.split("\\t",-1);if(p.length>=3&&"FIELD".equals(p[0]))fields.put(p[1],p[2]);else if(p.length>=4&&"APP".equals(p[0])&&!p[1].isBlank())apps.add(new String[]{p[1],p[2],p[3]});}if(fields.isEmpty())throw new IllegalStateException("PowerShell não retornou inventário: "+raw.substring(0,Math.min(500,raw.length())));return new Inventory(fields,apps);}
    private static String inventoryJson(Inventory i){StringBuilder b=new StringBuilder("{\"computer\":").append(q(System.getenv().getOrDefault("COMPUTERNAME","Windows PC"))).append(",\"fields\":{");boolean first=true;for(Map.Entry<String,String> e:i.fields.entrySet()){if(!first)b.append(',');first=false;b.append(q(e.getKey())).append(':').append(q(e.getValue()));}b.append("},\"installedPrograms\":[");for(int n=0;n<i.apps.size();n++){if(n>0)b.append(',');String[] a=i.apps.get(n);b.append("{\"name\":").append(q(a[0])).append(",\"version\":").append(q(a[1])).append(",\"publisher\":").append(q(a[2])).append('}');}return b.append("],\"capturedAt\":").append(q(Instant.now().toString())).append(",\"readOnly\":true}").toString();}
    private static final class Inventory{final Map<String,String> fields;final List<String[]> apps;Inventory(String[][] f,List<String[]> a){fields=new LinkedHashMap<>();for(String[] p:f)fields.put(p[0],p[1]);apps=a;}Inventory(Map<String,String> f,List<String[]> a){fields=f;apps=a;}}
    private static Snapshot snapshot(){OperatingSystemMXBean os=(OperatingSystemMXBean)ManagementFactory.getOperatingSystemMXBean();double cpu=os.getCpuLoad();long total=os.getTotalMemorySize(),free=os.getFreeMemorySize();long diskTotal=0,diskFree=0;for(File r:File.listRoots())try{diskTotal+=r.getTotalSpace();diskFree+=r.getFreeSpace();}catch(Exception ignored){}
        String boot=run(3000,"powershell.exe","-NoProfile","-NonInteractive","-Command","(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o')").trim();String active=activeWindow();return new Snapshot(cpu<0?-1:cpu*100,total,Math.max(0,total-free),diskTotal,Math.max(0,diskTotal-diskFree),boot,active,processesPlain());}
    private static String activeWindow(){String ps="$ErrorActionPreference='Stop'; try { $sig='[DllImport(\"user32.dll\", CharSet=CharSet.Auto)] public static extern IntPtr GetForegroundWindow(); [DllImport(\"user32.dll\", CharSet=CharSet.Auto)] public static extern int GetWindowText(IntPtr h, System.Text.StringBuilder s, int n);'; Add-Type -MemberDefinition $sig -Name Win -Namespace Marlico; $h=[Marlico.Win]::GetForegroundWindow(); $s=New-Object System.Text.StringBuilder 512; [void][Marlico.Win]::GetWindowText($h,$s,$s.Capacity); $s.ToString() } catch { '' }";String s=run(2500,"powershell.exe","-NoProfile","-NonInteractive","-WindowStyle","Hidden","-Command",ps).trim();return s.isEmpty()?"(nenhuma janela identificada)":s;}
    private static String run(int timeoutMs,String...args){try{Process p=new ProcessBuilder(args).redirectErrorStream(true).start();ByteArrayOutputStream capture=new ByteArrayOutputStream();Thread drain=new Thread(()->{try(InputStream in=p.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){synchronized(capture){if(capture.size()<2*1024*1024)capture.write(b,0,Math.min(n,2*1024*1024-capture.size()));}}}catch(IOException ignored){}});drain.setDaemon(true);drain.start();if(!p.waitFor(timeoutMs,TimeUnit.MILLISECONDS)){p.destroyForcibly();drain.join(1000);return "";}drain.join(1000);synchronized(capture){return capture.toString(StandardCharsets.UTF_8.name());}}catch(Exception e){return "";}}
    private static String statusJson(Snapshot s){return "{\"computer\":"+q(System.getenv().getOrDefault("COMPUTERNAME","Windows PC"))+",\"cpuPercent\":"+n(s.cpu)+",\"memoryTotalBytes\":"+s.memoryTotal+",\"memoryUsedBytes\":"+s.memoryUsed+",\"diskTotalBytes\":"+s.diskTotal+",\"diskUsedBytes\":"+s.diskUsed+",\"uptimeSeconds\":"+uptime(s.boot)+",\"activeWindow\":"+q(s.active)+",\"monitorCount\":"+GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices().length+",\"capturedAt\":"+q(Instant.now().toString())+",\"readOnly\":true}";}
    private static long uptime(String boot){try{return Math.max(0,Duration.between(Instant.parse(boot),Instant.now()).getSeconds());}catch(Exception e){return -1;}}
    private static String processesJson(){String raw=run(5000,"tasklist.exe","/FO","CSV","/NH");List<String> rows=new ArrayList<>();for(String line:raw.split("\\R")){List<String> col=parseCsv(line);if(col.size()<5)continue;String name=col.get(0);if(name.isEmpty())continue;long pid=number(col.get(1));long memory=number(col.get(4))*1024L;rows.add("{\"name\":"+q(name)+",\"pid\":"+pid+",\"memoryBytes\":"+memory+"}");if(rows.size()>=200)break;}return "{\"processes\":["+String.join(",",rows)+"],\"capturedAt\":"+q(Instant.now().toString())+"}";}
    private static List<String> parseCsv(String line){List<String> out=new ArrayList<>();StringBuilder b=new StringBuilder();boolean in=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(in&&i+1<line.length()&&line.charAt(i+1)=='"'){b.append('"');i++;}else in=!in;}else if(c==','&&!in){out.add(b.toString());b.setLength(0);}else b.append(c);}out.add(b.toString());return out;}
    private static long number(String s){try{return Long.parseLong(s.replaceAll("[^0-9]",""));}catch(Exception e){return 0;}}
    private static String q(String s){if(s==null)return "null";StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray()){switch(c){case '\\':b.append("\\\\");break;case '"':b.append("\\\"");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
    private static String n(double x){return String.format(Locale.US,"%.1f",x);}
    private static String statusText(Snapshot s){return "🖥 "+System.getenv().getOrDefault("COMPUTERNAME","Windows PC")+"\n⚙️ CPU: "+String.format(Locale.US,"%.0f%%",s.cpu)+"\n🧠 Memória: "+bytes(s.memoryUsed)+" / "+bytes(s.memoryTotal)+"\n💽 Armazenamento: "+bytes(s.diskUsed)+" / "+bytes(s.diskTotal)+"\n⏱ Ligado há: "+duration(uptime(s.boot))+"\n🪟 Janela ativa: "+s.active;}
    private static String bytes(long x){if(x<0)return "indisponível";String[] u={"B","KB","MB","GB","TB"};double v=x;int i=0;while(v>=1024&&i<u.length-1){v/=1024;i++;}return i==0?String.format(Locale.US,"%d %s",x,u[i]):String.format(Locale.US,"%.1f %s",v,u[i]);}
    private static String duration(long seconds){if(seconds<0)return "indisponível";long d=seconds/86400,h=seconds/3600%24,m=seconds/60%60;return d+"d "+h+"h "+m+"min";}
    private static Snapshot snapshotForApi(){return snapshot();}
    private static void render(Snapshot s){if(cpuLabel==null)return;cpuLabel.setText(s.cpu<0?"—":String.format(Locale.US,"%.0f%%",s.cpu));memLabel.setText(bytes(s.memoryUsed)+" / "+bytes(s.memoryTotal));diskLabel.setText(bytes(s.diskUsed)+" / "+bytes(s.diskTotal));uptimeLabel.setText(duration(uptime(s.boot)));windowLabel.setText("Janela ativa: "+s.active);processModel.setRowCount(0);for(String line:s.processes.split("\\R")){String[] c=line.split("\\t",-1);if(c.length==3)processModel.addRow(c);}}
    private static String processesPlain(){String raw=run(5000,"tasklist.exe","/FO","CSV","/NH");StringBuilder out=new StringBuilder();int count=0;for(String line:raw.split("\\R")){List<String> c=parseCsv(line);if(c.size()<5||c.get(0).isEmpty())continue;out.append(c.get(0)).append('\t').append(c.get(1)).append('\t').append(c.get(4)).append('\n');if(++count>=35)break;}return out.toString();}
    private static String bytesForTelegram(long n){return bytes(n);}
    private static void pairingHelp(){brandedMessage("Pareamento pela rede local","No MarlicoBot do celular ou TV Box, abra Monitorar PC e toque em “Parear pela rede local”. Confira se o IP do Windows informado no app corresponde a este computador. Um pedido aparecerá aqui; aprove somente se você mesmo iniciou o pareamento.");}
    private static List<String> networkIpv4s(){List<String> out=new ArrayList<>();try{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface ni=all.nextElement();String name=(ni.getName()+" "+ni.getDisplayName()).toLowerCase(Locale.ROOT);if(!ni.isUp()||ni.isLoopback()||name.matches(".*(virtual|vpn|vmware|virtualbox|vethernet|docker|wsl|tunnel|loopback).*"))continue;Enumeration<InetAddress> as=ni.getInetAddresses();while(as.hasMoreElements()){InetAddress a=as.nextElement();if(a instanceof Inet4Address&&a.isSiteLocalAddress()&&!out.contains(a.getHostAddress()))out.add(a.getHostAddress());}}}catch(Exception ignored){}Collections.sort(out);if(out.isEmpty())out.add("Nenhum IPv4 privado detectado");return out;}
    private static void firewallRule(){if(!brandedConfirm("Permitir conexão na rede local","Para conectar o app a este PC, o Windows solicitará autorização para uma regra de entrada TCP na porta "+PORT+", limitada à sub-rede local. O agente não ficará exposto à internet.","Continuar para o UAC","Cancelar"))return;try{String command="Start-Process PowerShell -Verb RunAs -ArgumentList '-NoProfile -Command New-NetFirewallRule -DisplayName MarlicoBot-PC -Direction Inbound -Action Allow -Protocol TCP -LocalPort "+PORT+" -RemoteAddress LocalSubnet'";new ProcessBuilder("powershell.exe","-NoProfile","-Command",command).start();}catch(Exception e){brandedMessage("Regra de rede não criada","Não foi possível solicitar a regra do firewall. Crie uma regra de entrada TCP "+PORT+" limitada à rede privada.");}}
    private static String loadToken() throws Exception {Properties p=new Properties();if(Files.exists(PREFS))try(InputStream in=Files.newInputStream(PREFS)){p.load(in);}unattendedScreenAllowed=Boolean.parseBoolean(p.getProperty("unattendedScreenAllowed","false"));String value=p.getProperty("token");if(value==null||value.length()<40){byte[] b=new byte[32];new SecureRandom().nextBytes(b);value=Base64.getUrlEncoder().withoutPadding().encodeToString(b);p.setProperty("token",value);try(OutputStream out=Files.newOutputStream(PREFS)){p.store(out,"MarlicoBot PC agent secret");}}return value;}
